-- 脚本/core/templates.lua
-- 模板图库（base64 内嵌）+ 设备文件写入 + OpenCV 匹配工具
-- 生成来源：D:/project/mzxy/image-test 截图裁剪（2026-09-28）
-- 用法：
--   local tpl = require("core.templates")
--   local r = tpl.match("exit_spiral", {1090,5,1275,195}, 0.68)
--   -- r = { sim, x, y(中心), left, top, w, h } 或 nil(未达阈值), low(最高分)
local _M = {}

_M.CFG = { tmpDir = "saoif_tpl" }

local paths, mats = {}, {}

_M.exit_spiral = ""

_M.magnifier = ""

_M.ok_btn = ""

_M.marker = ""

-- 确保模板已写入设备文件
local function ensure(key)
    if paths[key] then return true end
    local b64 = _M[key]
    if not b64 then return false end
    local dir = getSdPath() .. "/" .. _M.CFG.tmpDir
    pcall(mkdir, dir)
    local path = dir .. "/" .. key .. ".png"
    local f = io.open(path, "wb")
    if not f then return false end
    f:write(decodeBase64(b64))
    f:close()
    paths[key] = path
    return true
end

-- 取模板 Mat（缓存的 cv Mat）
function _M.mat(key)
    if mats[key] then return mats[key] end
    if not ensure(key) then return nil end
    local m = cv.imread(paths[key], cv.IMREAD_COLOR)
    mats[key] = m
    return m
end

-- 在 roi={x1,y1,x2,y2} 内匹配模板
-- 返回: ok{sim,x,y,left,top,w,h}         匹配达到阈值
--       nil, low{...}                    未达阈值（low=最高分位置）
--       nil, nil, err                    错误
function _M.match(key, roi, simMin)
    local tm = _M.mat(key)
    if not tm then return nil, nil, "no_tpl" end
    local x1, y1, x2, y2 = roi[1], roi[2], roi[3], roi[4]
    local scr = cv.snapShot(x1, y1, x2, y2)
    if not scr then return nil, nil, "no_shot" end
    local res = cv.Mat.new()
    cv.matchTemplate(scr, tm, res, cv.TM_CCOEFF_NORMED)
    local mn = cv.newPoint(0, 0)
    local mx = cv.newPoint(0, 0)
    local mnv = cv.newDouble(0)
    local mxv = cv.newDouble(0)
    cv.minMaxLoc(res, mnv, mxv, mn, mx)
    local p = cv.getPoint(mx)
    local sim = cv.getDouble(mxv)
    local o = { sim = sim, left = x1 + p.x, top = y1 + p.y, w = tm.cols, h = tm.rows }
    o.x = o.left + o.w / 2
    o.y = o.top + o.h / 2
    res:release()
    scr:release()
    cv.deletePtr(mn); cv.deletePtr(mx); cv.deletePtr(mnv); cv.deletePtr(mxv)
    if simMin and sim < simMin then return nil, o end
    return o, o
end

return _M
